import { foregroundInitialOffset, foregroundSquareExtraTravel, foregroundParallaxSmall, foregroundParallaxLarge } from '../../common/constants/heroUnitConstants.js';

const customEasing = (t, p0, p1, p2, p3) => (1 - t) ** 3 * p0 + 3 * (1 - t) ** 2 * t * p1 + 3 * (1 - t) * t ** 2 * p2 + t ** 3 * p3;
const easeBidirectional = (t) => {
    const clampedT = Math.max(-1, Math.min(t, 1));
    if (clampedT >= 0) {
        return customEasing(clampedT, 0, 0.3, 0.6, 1);
    }
    return -customEasing(-clampedT, 0, 0.3, 0.6, 1);
};
const captureInitialNormalizedTopPosition = (normalizedDistanceFromTop, rectTop) => {
    if (normalizedDistanceFromTop >= 1) {
        return 1;
    }
    if (rectTop > 0) {
        return normalizedDistanceFromTop;
    }
    return 1;
};
const calculateScrollProgress = (normalizedDistanceFromTop, initialNormalizedTopPosition, normalizedHeroUnitHeight) => {
    if (normalizedDistanceFromTop >= 0) {
        return Math.min(1, normalizedDistanceFromTop / initialNormalizedTopPosition);
    }
    return normalizedHeroUnitHeight > 0
        ? Math.max(-1, normalizedDistanceFromTop / normalizedHeroUnitHeight)
        : -1;
};
const calculateForegroundParallaxMagnitudes = ({ isSmallView, foregroundAspectRatio, bgHeight }) => {
    const foregroundOverflow = isSmallView ? foregroundParallaxSmall : foregroundParallaxLarge;
    const containerHeight = bgHeight + foregroundOverflow;
    const fgHeight = bgHeight / foregroundAspectRatio;
    const fgMax = foregroundAspectRatio === 1
        ? foregroundOverflow + foregroundInitialOffset
        : foregroundOverflow - foregroundInitialOffset;
    let fgMin = -(fgHeight - containerHeight);
    if (foregroundAspectRatio === 1) {
        fgMin -= foregroundSquareExtraTravel;
    }
    return {
        fgMax,
        fgMinMagnitude: Math.abs(fgMin)
    };
};

export { calculateForegroundParallaxMagnitudes, calculateScrollProgress, captureInitialNormalizedTopPosition, customEasing, easeBidirectional };
